class CourseModel { final String id,name,schoolId,description; final double employmentScore; CourseModel({required this.id,required this.name,required this.schoolId,this.description='',this.employmentScore=0}); factory CourseModel.fromJson(Map<String,dynamic> j)=>CourseModel(id:j['id'],name:j['name'],schoolId:j['schoolId'],description:j['description']??'',employmentScore:double.tryParse('${j['employmentScore']??0}')??0); }
class CourseOfferingModel { final String id,courseId,examBody,level,minimumGrade; final int durationMonths,numberOfTerms; final double tuitionFeePerTerm,practicalFeePerTerm; CourseOfferingModel({required this.id,required this.courseId,required this.examBody,required this.level,required this.durationMonths,required this.numberOfTerms,required this.tuitionFeePerTerm,required this.practicalFeePerTerm,this.minimumGrade=''}); factory CourseOfferingModel.fromJson(Map<String,dynamic> j)=>CourseOfferingModel(id:j['id'],courseId:j['courseId'],examBody:j['examBody']?['code']??j['examBody']??'',level:j['level'],durationMonths:j['durationMonths'],numberOfTerms:j['numberOfTerms'],tuitionFeePerTerm:double.parse('${j['tuitionFeePerTerm']}'),practicalFeePerTerm:double.parse('${j['practicalFeePerTerm']}'),minimumGrade:j['minimumGrade']??''); }
class FeeBreakdownModel { final double totalPayable; final List<Map<String,dynamic>> lineItems; FeeBreakdownModel({required this.totalPayable,required this.lineItems}); factory FeeBreakdownModel.fromJson(Map<String,dynamic> j)=>FeeBreakdownModel(totalPayable:double.parse('${j['totalPayable']}'),lineItems:List<Map<String,dynamic>>.from(j['lineItems']??[])); }
class EligibilityResultModel { final bool eligible; final String recommendedPath; final List<String> reasons; EligibilityResultModel({required this.eligible,required this.recommendedPath,required this.reasons}); factory EligibilityResultModel.fromJson(Map<String,dynamic> j)=>EligibilityResultModel(eligible:j['eligible']==true,recommendedPath:j['recommendedPath']??'',reasons:List<String>.from(j['reasons']??[])); }
